fn intersperse(numbers: &[i32], delim: i32) -> Vec<i32> {
    let n = numbers.len();
    // Compute the needed capacity: if there are n > 0 elements,
    // we'll end up with (2*n - 1) slots; otherwise zero.
    let cap = if n > 0 { 2 * n - 1 } else { 0 };
    let mut res = Vec::with_capacity(cap);

    for (i, &num) in numbers.iter().enumerate() {
        // For every element except the first, insert the delimiter before it.
        if i > 0 {
            res.push(delim);
        }
        res.push(num);
    }

    res
}

